-- ============================================
-- ORIGENES: por dónde ingresó la solicitud (Mesa de partes virtual, ODE ...)
-- ============================================
CREATE TABLE IF NOT EXISTS "ORIGENES" (
    "ID_ORIGEN" INT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT "PK_ORIGENES" PRIMARY KEY,
    "NOMBRE" VARCHAR(100) NOT NULL CONSTRAINT "UQ_ORIGENES_NOMBRE" UNIQUE,
    "ACTIVO" BOOLEAN NOT NULL DEFAULT TRUE
);
